    RAISE EXCEPTION '074b proof: a trigger appeared';
  END IF;
  RAISE NOTICE '074b OK: 5 new checks (B-95..B-99), 3 rewritten (B-10, B-26, B-42), the runner reads day L, every check 0 today';
  RAISE EXCEPTION 'DRY RUN 074b finished - EVERYTHING UNDONE, nothing kept.';
END
$dry$;
